#include <vector>

class Solution {
public:
    int diagonalSum(std::vector<std::vector<int>>& mat) {
        int n = mat.size(), ans = 0;
        for (int i = 0; i < n; ++i) {
            ans += mat[i][i] + mat[i][n - 1 - i];
        }
        if (n % 2 == 1) ans -= mat[n / 2][n / 2];
        return ans;
    }
};

class Solution {
    public int diagonalSum(int[][] mat) {
        int n = mat.length, ans = 0;
        for (int i = 0; i < n; i++) {
            ans += mat[i][i] + mat[i][n - 1 - i];
        }
        if (n % 2 == 1) ans -= mat[n / 2][n / 2];
        return ans;
    }
}

var diagonalSum = function(mat) {
    const n = mat.length;
    let ans = 0;
    for (let i = 0; i < n; i++) {
        ans += mat[i][i] + mat[i][n - 1 - i];
    }
    if (n % 2 === 1) {
        ans -= mat[Math.floor(n / 2)][Math.floor(n / 2)];
    }
    return ans;
};
